const test=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),os=require('node:os'),path=require('node:path'),brand=require('../src/windows-brand.cjs');
test('taskbar identity and owned shortcuts use the same Narae icon without changing other Electron apps',()=>{const root=fs.mkdtempSync(path.join(os.tmpdir(),'narae-brand-')),desktop=path.join(root,'desktop'),data=path.join(root,'appdata'),pinned=path.join(data,'Microsoft/Internet Explorer/Quick Launch/User Pinned/TaskBar');fs.mkdirSync(desktop,{recursive:true});fs.mkdirSync(pinned,{recursive:true});for(const file of [path.join(desktop,'narae.lnk'),path.join(desktop,'other-electron.lnk'),path.join(pinned,'pinned-narae.lnk')])fs.writeFileSync(file,'fixture');const executable=path.join(root,'electron.exe'),updates=[];let details,icon,id;const result=brand.apply({root,executable,platform:'win32',app:{setAppUserModelId:value=>{id=value;},getPath:key=>key==='desktop'?desktop:data},window:{setIcon:value=>{icon=value;},setAppDetails:value=>{details=value;}},shell:{readShortcutLink:file=>({target:executable,args:file.includes('other-electron')?'"D:/OtherApp"':'"'+root+'"'}),writeShortcutLink:(file,operation,value)=>{updates.push({file,operation,value});return true;}}});assert.equal(result.updated,2);assert.equal(details.appId,id);assert.equal(details.appIconPath,icon);assert.equal(details.relaunchDisplayName,'나래 한글 오피스');assert.equal(details.relaunchCommand,'"'+executable+'" "'+root+'"');assert(updates.every(u=>u.operation==='update'&&u.value.icon===icon&&u.value.appUserModelId===id&&!u.file.includes('other-electron')));});
